def power(a, b):
    # Base case: any number to the power of 0 is 1
    if b == 0:
        return 1
    # Base case: 0 to the power of any number (except 0) is 0
    elif a == 0:
        return 0
    # Base case: any number to the power of 1 is the number itself
    elif b == 1:
        return a
    # Recursive case: multiply the number by itself (b-1) times
    else:
        return a * power(a, b - 1)
